<?php
session_start();
require_once __DIR__ . '/conexion.php';
if (empty($_SESSION['id_usuario']) || ($_SESSION['rol'] ?? '') !== 'administrador') { http_response_code(403); exit('Acceso restringido.'); }
function h($v) { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }
if (empty($_SESSION['csrf_tm'])) $_SESSION['csrf_tm'] = bin2hex(random_bytes(32));
function check_post() { if (!hash_equals($_SESSION['csrf_tm'], (string)($_POST['csrf'] ?? ''))) { http_response_code(403); exit('Solicitud inválida'); } }
function num_id($v) { $x=filter_var($v,FILTER_VALIDATE_INT); return $x && $x>0 ? (int)$x : null; }
function opt_id($v) { return ($v === '' || $v === null) ? null : num_id($v); }
function choices($sql) { global $conexion; return $conexion->query($sql)->fetchAll(PDO::FETCH_ASSOC); }
function dt($v) { if (!$v) return null; $d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i', $v); return $d && $d->format('Y-m-d\TH:i') === $v ? $d->format('Y-m-d H:i:s') : false; }
$error='';
$success=isset($_GET['ok']);
$estaciones=choices('SELECT id_estacion,nombre FROM estaciones ORDER BY nombre');
if ($_SERVER['REQUEST_METHOD']==='POST') {check_post();$origen=num_id($_POST['origen']??null);$dest=opt_id($_POST['destino']??'');$tec=$_POST['tecnologia']??'';$obs=trim($_POST['observaciones']??'');
 if (!$origen || (($_POST['destino']??'')!=='' && !$dest) || ($dest && $dest===$origen) || !in_array($tec,['fibra','vpn','sd_wan','celular','pendiente'],true) || mb_strlen($obs)>255) $error='Revisa los datos del enlace.';
 else {try{$s=$conexion->prepare('INSERT INTO enlaces_conectividad(id_estacion_origen,id_estacion_destino,tecnologia,observaciones) VALUES (?,?,?,?)');$s->execute([$origen,$dest,$tec,$obs]);header('Location: conectividad.php?ok=1');exit;}catch(PDOException $e){error_log($e->getMessage());$error='No se pudo registrar el enlace.';}}
}
$rows=choices('SELECT c.*,e1.nombre AS origen,e2.nombre AS destino FROM enlaces_conectividad c JOIN estaciones e1 ON e1.id_estacion=c.id_estacion_origen LEFT JOIN estaciones e2 ON e2.id_estacion=c.id_estacion_destino ORDER BY c.id_enlace DESC LIMIT 150');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conectividad de estaciones · Transmetro</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f7fb;color:#1c2d45}.navbar{background:#14253e}.card{border:0;border-radius:18px;box-shadow:0 8px 25px #152e4a13}.btn-brand{background:#f0a72e;font-weight:700}.table{font-size:.91rem}</style></head><body><nav class="navbar navbar-dark"><div class="container"><a class="navbar-brand fw-bold" href="panel.php">Transmetro Info</a><a class="btn btn-outline-light btn-sm" href="panel.php">Volver al panel</a></div></nav><main class="container py-5"><h1 class="h2 fw-bold">Conectividad de estaciones</h1><p class="text-secondary">Proyecto académico · Datos de demostración</p><?php if ($success): ?><div class="alert alert-success">Registro guardado correctamente.</div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?=h($error)?></div><?php endif; ?><div class="card mb-4"><div class="card-body p-4"><h2 class="h5">Nuevo registro</h2><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf_tm'])?>"><div class="col-md-6"><label class="form-label">Estación de origen</label><select class="form-select" name="origen" required><option value="">Seleccionar</option><?php foreach ($estaciones as $v): ?><option value="<?=h($v['id_estacion'])?>"><?=h($v['nombre'])?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Estación de destino (opcional)</label><select class="form-select" name="destino"  ><option value="">Ninguno</option><?php foreach ($estaciones as $v): ?><option value="<?=h($v['id_estacion'])?>"><?=h($v['nombre'])?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Tecnología</label><select name="tecnologia" class="form-select"><option value="pendiente">Pendiente de definir</option><option value="fibra">Fibra óptica</option><option value="vpn">VPN</option><option value="sd_wan">SD-WAN</option><option value="celular">Celular</option></select></div><div class="col-md-6"><label class="form-label">Observaciones</label><input class="form-control" type="text" name="observaciones" maxlength="255"></div><div class="col-12"><button class="btn btn-brand">Guardar</button></div></form></div></div><div class="card"><div class="card-body p-4"><h2 class="h5">Registros</h2><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Origen</th><th>Destino</th><th>Tecnología</th><th>Observaciones</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?=h($r['origen'])?></td><td><?=h($r['destino'])?></td><td><?=h($r['tecnologia'])?></td><td><?=h($r['observaciones'])?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="4">Aún no hay registros.</td></tr><?php endif; ?></tbody></table></div></div></div></main></body></html>